insert into public.questions
(exam_category, subject, topic, type, difficulty, body, question_data, options, marks_correct, marks_wrong, explanation, concept_group_id, source_type, source_citation, status)
values
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','medium','Consider the following statements about the olive ridley turtle:','{"statements": ["It is known for ''arribada'', a synchronised mass nesting in which thousands of females come ashore together.", "Gahirmatha, the mouth of the Rushikulya and the mouth of the Devi river in Odisha are among its main mass-nesting sites.", "It is listed in Schedule I of the Wildlife (Protection) Act, 1972."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 and 2 only", "isCorrect": false}, {"id": "b", "body": "2 and 3 only", "isCorrect": false}, {"id": "c", "body": "1 and 3 only", "isCorrect": false}, {"id": "d", "body": "1, 2 and 3", "isCorrect": true}]'::jsonb,2,0.66,'All three statements are correct. Olive ridleys nest en masse (''arribada''), and Odisha''s Gahirmatha, Rushikulya and Devi river mouth are among the world''s largest such rookeries. Like every sea turtle in Indian waters, the olive ridley is in Schedule I of the Wildlife (Protection) Act; it is listed as Vulnerable by the IUCN. It is one of the smallest sea turtles -- the leatherback is the largest.','env-olive-ridley-arribada','original_pattern_matched','IUCN Red List of Threatened Species, Lepidochelys olivacea; Wildlife (Protection) Act, 1972 (as amended in 2022), Schedule I; Odisha Forest Department, sea-turtle rookeries.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','medium','Consider the following statements about the red panda:','{"statements": ["It belongs to the same family as the giant panda.", "It is the State animal of Sikkim.", "Its diet consists mainly of bamboo leaves and shoots."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": true}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Only statements 2 and 3 are correct. The red panda is Sikkim''s State animal and feeds mostly on bamboo. Statement 1 is the trap: despite the shared name and diet, the red panda is the only living member of its own family, Ailuridae, while the giant panda is a bear (Ursidae). It is listed as Endangered by the IUCN.','env-red-panda','original_pattern_matched','IUCN Red List of Threatened Species, Ailurus fulgens; Government of Sikkim, State symbols.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','medium','Consider the following statements about the Great Indian Bustard:','{"statements": ["It is listed as Critically Endangered on the IUCN Red List.", "Collision with overhead power lines is a major cause of death of the Great Indian Bustard in the Thar."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "isCorrect": false}, {"id": "b", "body": "2 only", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct. The Great Indian Bustard is Critically Endangered, with most of the surviving birds in Rajasthan''s Thar. Because it has poor frontal vision and flies low and heavily, it frequently collides with overhead power lines; Wildlife Institute of India studies identified these collisions as a leading cause of adult deaths, which is why undergrounding of lines in its habitat has been ordered.','env-great-indian-bustard-powerlines','original_pattern_matched','IUCN Red List of Threatened Species, Ardeotis nigriceps; Wildlife Institute of India, power-line mortality assessment in the Thar.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','medium','Consider the following statements:','{"statements": ["Aestivation is a state of dormancy that some animals enter to survive hot, dry periods.", "Hibernation is seen only in mammals; no reptile or amphibian hibernates.", "The African lungfish survives the drying of its pool by aestivating inside a mucus cocoon in the mud."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 and 2 only", "isCorrect": false}, {"id": "b", "body": "2 and 3 only", "isCorrect": false}, {"id": "c", "body": "1 and 3 only", "isCorrect": true}, {"id": "d", "body": "1, 2 and 3", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 3 are correct. Aestivation is summer dormancy in response to heat and drought; the African lungfish is the classic example, sealing itself in a mucus cocoon when its pool dries up. Statement 2 is wrong: many reptiles and amphibians (frogs, turtles, snakes) pass the winter in a dormant state, so hibernation is not confined to mammals.','env-aestivation-hibernation','original_pattern_matched','NCERT Biology Class XII, ch. ''Organisms and Populations'' (responses to abiotic factors).','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','medium','Consider the following statements about horseshoe crabs:','{"statements": ["They are more closely related to spiders and scorpions than to true crabs.", "Their blood is red because it carries oxygen with haemoglobin.", "An extract of their blood is used to test vaccines and medical devices for bacterial endotoxins.", "In India they are found only around the Andaman and Nicobar Islands."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": true}, {"id": "c", "body": "Only three", "isCorrect": false}, {"id": "d", "body": "All four", "isCorrect": false}]'::jsonb,2,0.66,'Only statements 1 and 3 are correct. Horseshoe crabs are chelicerates, grouped with spiders and scorpions. Their blood is blue, not red: oxygen is carried by the copper-based protein haemocyanin. Amoebocyte lysate made from their blood is the standard test for bacterial endotoxins in injectable drugs and devices. In India they occur along the east coast, notably Odisha (Balasore) and West Bengal, not only in the Andaman and Nicobar Islands.','env-horseshoe-crab','original_pattern_matched','Zoological Survey of India, horseshoe crabs of India; US FDA guidance on bacterial endotoxins testing (LAL).','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','medium','Consider the following statements about the sloth bear:','{"statements": ["It feeds largely on termites and ants, which it sucks up through a gap left by missing upper front teeth.", "It is found only in India.", "Mothers carry their cubs on their backs."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "isCorrect": false}, {"id": "b", "body": "1 and 3", "isCorrect": true}, {"id": "c", "body": "2 and 3", "isCorrect": false}, {"id": "d", "body": "3 only", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 3 are correct. The sloth bear is a specialist insect-eater: it lacks the upper incisors and uses the gap and its mobile lips to suck termites and ants from their mounds. Mothers carry cubs on their backs. Statement 2 is wrong -- the species also lives in Sri Lanka and Nepal. It is listed as Vulnerable by the IUCN.','env-sloth-bear','original_pattern_matched','IUCN Red List of Threatened Species, Melursus ursinus.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','medium','Consider the following statements about seahorses:','{"statements": ["The male carries the fertilised eggs in a brood pouch until they hatch.", "Seahorses are fish.", "All seahorse species are listed in Appendix II of CITES."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "All three", "isCorrect": true}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. In seahorses the female deposits eggs in the male''s brood pouch, where they are fertilised and carried until the young emerge. Seahorses are bony fish of the family Syngnathidae (with pipefishes). Since 2004 the whole genus Hippocampus has been listed in CITES Appendix II, because of heavy trade for traditional medicine and aquariums.','env-seahorse-male-pregnancy','original_pattern_matched','CITES Appendices (Hippocampus spp., Appendix II); Zoological Survey of India, syngnathid fishes.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','medium','Consider the following statements about the snow leopard:','{"statements": ["It is listed as Vulnerable on the IUCN Red List.", "In India its range covers the high Himalaya of Ladakh, Jammu & Kashmir, Himachal Pradesh, Uttarakhand, Sikkim and Arunachal Pradesh.", "India''s first Snow Leopard Population Assessment, released in 2024, estimated fewer than 200 snow leopards in the country."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true, "numbering": "roman"}'::jsonb,'[{"id": "a", "body": "I and II only", "isCorrect": true}, {"id": "b", "body": "II and III only", "isCorrect": false}, {"id": "c", "body": "I and III only", "isCorrect": false}, {"id": "d", "body": "I, II and III", "isCorrect": false}]'::jsonb,2,0.66,'Statements I and II are correct. The snow leopard was moved from Endangered to Vulnerable by the IUCN in 2017. India''s range runs across the high Himalaya, from Ladakh to Arunachal Pradesh. Statement III is wrong: the Snow Leopard Population Assessment in India (SPAI), released in January 2024, estimated 718 snow leopards, more than half of them (477) in Ladakh.','env-snow-leopard-spai','original_pattern_matched','IUCN Red List of Threatened Species, Panthera uncia; MoEFCC / Wildlife Institute of India, Status of Snow Leopards in India (SPAI), January 2024.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','easy','Consider the following statements about vultures in India:','{"statements": ["Vultures are scavengers that feed mainly on carcasses.", "The collapse of India''s Gyps vulture populations was caused mainly by DDT residues in carcasses.", "Veterinary use of diclofenac is still permitted in India."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": true}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. The crash of India''s Gyps vultures from the 1990s was traced to diclofenac, a painkiller given to cattle: vultures feeding on treated carcasses suffered kidney failure. DDT was not the cause. India banned veterinary use of diclofenac in 2006, so statement 3 is also wrong.','env-vultures-diclofenac','original_pattern_matched','Ministry of Health and Family Welfare, ban on veterinary diclofenac (2006); MoEFCC, Action Plan for Vulture Conservation in India 2020-25.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','easy','Consider the following statements about echolocation:','{"statements": ["Bats and dolphins use echolocation to locate their prey.", "Echolocation is used only by nocturnal animals."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "isCorrect": true}, {"id": "b", "body": "2 only", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. Echolocating animals emit sounds and interpret the returning echoes; bats and toothed whales such as dolphins are the best-known examples. It is not limited to night-active animals -- dolphins hunt by echolocation by day as well, in murky water.','env-echolocation','original_pattern_matched','NCERT Biology Class XII, ch. ''Organisms and Populations''.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','easy','Consider the following statements about the blackbuck:','{"statements": ["It is an antelope of open grasslands and scrub.", "It is the State animal of Punjab.", "The Bishnoi community is known for protecting it."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 and 2 only", "isCorrect": false}, {"id": "b", "body": "2 and 3 only", "isCorrect": false}, {"id": "c", "body": "1 and 3 only", "isCorrect": false}, {"id": "d", "body": "1, 2 and 3", "isCorrect": true}]'::jsonb,2,0.66,'All three statements are correct. The blackbuck is an antelope of open plains and grassland. It is the State animal of Punjab (as well as of Haryana and Andhra Pradesh). The Bishnoi community of Rajasthan is known for protecting blackbuck and chinkara. It is in Schedule I of the Wildlife (Protection) Act.','env-blackbuck','original_pattern_matched','IUCN Red List of Threatened Species, Antilope cervicapra; Wildlife (Protection) Act, 1972 (as amended in 2022), Schedule I.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','hard','Consider the following statements about birds of India:','{"statements": ["The Forest Owlet, once thought extinct, was rediscovered in 1997 in the forests of Maharashtra.", "Jerdon''s Courser was rediscovered in 1986 in Andhra Pradesh.", "The Pink-headed Duck has not been reliably recorded in the wild since the late 1940s.", "The Great Indian Bustard is the State bird of Rajasthan."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "Only three", "isCorrect": false}, {"id": "d", "body": "All four", "isCorrect": true}]'::jsonb,2,0.66,'All four statements are correct. The Forest Owlet was rediscovered in 1997 near Shahada in Maharashtra, over a century after the last specimen. Jerdon''s Courser was rediscovered in 1986 in the Lankamalleswara area of Andhra Pradesh. The Pink-headed Duck has had no confirmed record since 1949 and may be extinct. The Great Indian Bustard (godawan) is Rajasthan''s State bird. The difficulty is that each fact sounds improbable, so candidates tend to under-count.','env-rediscovered-birds','original_pattern_matched','BirdLife International species factsheets (Heteroglaux blewitti, Rhinoptilus bitorquatus, Rhodonessa caryophyllacea); Government of Rajasthan, State symbols.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','hard','Consider the following statements about fish migration:','{"statements": ["Hilsa is an anadromous fish: it lives in the sea and moves up rivers to spawn.", "Freshwater eels are catadromous: they live in rivers and migrate to the sea to spawn.", "Salmon are catadromous fish."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true, "numbering": "roman"}'::jsonb,'[{"id": "a", "body": "I and III only", "isCorrect": false}, {"id": "b", "body": "I and II only", "isCorrect": true}, {"id": "c", "body": "II and III only", "isCorrect": false}, {"id": "d", "body": "I, II and III", "isCorrect": false}]'::jsonb,2,0.66,'Statements I and II are correct. Anadromous fish (hilsa, salmon) grow in the sea and migrate into rivers to breed; catadromous fish (freshwater eels) do the reverse. Statement III therefore gets salmon backwards -- salmon are the textbook anadromous fish.','env-anadromous-catadromous','original_pattern_matched','ICAR-Central Inland Fisheries Research Institute, hilsa biology; FAO fisheries glossary (anadromous, catadromous).','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','hard','Consider the following statements about the king cobra:','{"statements": ["It belongs to the same genus as the Indian spectacled cobra.", "It is the only snake known to build a nest for its eggs.", "It feeds mainly on other snakes."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": true}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Only statements 2 and 3 are correct. The female king cobra gathers leaf litter into a nest and guards it, which no other snake is known to do; its diet is chiefly other snakes, hence its genus name Ophiophagus (''snake-eater''). That also makes statement 1 wrong: the spectacled cobra is Naja naja, a different genus. The king cobra is listed as Vulnerable.','env-king-cobra','original_pattern_matched','IUCN Red List of Threatened Species, Ophiophagus hannah.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','mcq','medium','The wool of which animal, protected in India, is used to make ''shahtoosh'' shawls?','{}'::jsonb,'[{"id": "a", "body": "Himalayan tahr", "isCorrect": false}, {"id": "b", "body": "Bharal", "isCorrect": false}, {"id": "c", "body": "Markhor", "isCorrect": false}, {"id": "d", "body": "Tibetan antelope (chiru)", "isCorrect": true}]'::jsonb,2,0.66,'Shahtoosh is woven from the fine underwool of the Tibetan antelope, or chiru, which must be killed to obtain it. The chiru lives on the Tibetan plateau and in Ladakh''s Changthang; it is in Schedule I of the Wildlife (Protection) Act and in CITES Appendix I, and trade in shahtoosh is banned.','env-chiru-shahtoosh','original_pattern_matched','Wildlife (Protection) Act, 1972 (as amended in 2022), Schedule I; CITES Appendix I (Pantholops hodgsonii).','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','mcq','medium','Which one of the following birds lays its eggs in the nests of crows and leaves the crows to raise its young?','{}'::jsonb,'[{"id": "a", "body": "Asian koel", "isCorrect": true}, {"id": "b", "body": "House sparrow", "isCorrect": false}, {"id": "c", "body": "Indian robin", "isCorrect": false}, {"id": "d", "body": "Common myna", "isCorrect": false}]'::jsonb,2,0.66,'The Asian koel is a brood parasite: the female lays her eggs in crows'' nests and the crows rear the chicks. Brood parasitism is an interaction in which one species exploits another''s parental care.','env-koel-brood-parasite','original_pattern_matched','NCERT Biology Class XII, ch. ''Organisms and Populations'' (population interactions: brood parasitism).','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','mcq','easy','Which animal was declared India''s ''National Heritage Animal'' in 2010?','{}'::jsonb,'[{"id": "a", "body": "Tiger", "isCorrect": false}, {"id": "b", "body": "Elephant", "isCorrect": true}, {"id": "c", "body": "Asiatic lion", "isCorrect": false}, {"id": "d", "body": "Gaur", "isCorrect": false}]'::jsonb,2,0.66,'The Indian elephant was declared the National Heritage Animal in 2010, on the recommendation of the Elephant Task Force. The tiger remains the national animal.','env-elephant-heritage-animal','original_pattern_matched','MoEFCC, notification declaring the elephant the National Heritage Animal (2010); Elephant Task Force report ''Gajah'' (2010).','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','mcq','hard','The Hangul (Kashmir stag), the State animal of Jammu and Kashmir, survives mainly in which protected area?','{}'::jsonb,'[{"id": "a", "body": "Hemis National Park", "isCorrect": false}, {"id": "b", "body": "Great Himalayan National Park", "isCorrect": false}, {"id": "c", "body": "Dachigam National Park", "isCorrect": true}, {"id": "d", "body": "Valley of Flowers National Park", "isCorrect": false}]'::jsonb,2,0.66,'The last viable Hangul population is centred on Dachigam National Park near Srinagar. Hemis is in Ladakh (snow leopard country), the Great Himalayan NP in Himachal Pradesh and the Valley of Flowers in Uttarakhand.','env-hangul-dachigam','original_pattern_matched','Department of Wildlife Protection, Jammu & Kashmir, Dachigam National Park; Wildlife Institute of India, Hangul conservation.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','assertion_reason','easy','Consider the following statements:','{"assertion": "Camels can survive long periods without drinking water.", "reason": "Camels store water in their humps.", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "isCorrect": false}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "isCorrect": true}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "isCorrect": false}]'::jsonb,2,0.66,'Statement-I is correct: camels tolerate long periods without drinking, thanks to efficient kidneys, very dry dung and tolerance of dehydration. Statement-II is the popular misconception: the hump stores fat, not water.','env-camel-hump-fat','original_pattern_matched','NCERT Biology Class XII, ch. ''Organisms and Populations'' (adaptations to desert conditions).','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','assertion_reason','medium','Consider the following statements:','{"assertion": "Arctic foxes have short ears and a short muzzle.", "reason": "Arctic foxes change the colour of their coat with the seasons.", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "isCorrect": false}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "isCorrect": true}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct, but Statement-II does not explain Statement-I. Short ears and muzzle cut heat loss in the cold (Allen''s rule: mammals of cold climates have shorter extremities). The seasonal coat change -- white in winter, brown or grey in summer -- is camouflage, a separate adaptation.','env-arctic-fox-allens-rule','original_pattern_matched','NCERT Biology Class XII, ch. ''Organisms and Populations'' (Allen''s rule).','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','assertion_reason','hard','Consider the following statements:','{"assertion": "Bar-headed geese can fly over the Himalaya during their migration.", "reason": "The haemoglobin of bar-headed geese has a higher affinity for oxygen than that of lowland geese, helping them take up oxygen in thin air.", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "isCorrect": true}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct and Statement-II explains Statement-I. Bar-headed geese cross the Himalaya between Central Asia and India. Their haemoglobin binds oxygen more strongly, which lets them load enough oxygen at altitudes where the air is very thin.','env-bar-headed-goose','original_pattern_matched','Scott, G. R. et al. (2015), ''How bar-headed geese fly over the Himalayas'', Physiology 30(2).','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','match_the_following','medium','Consider the following pairs of animals and the States of which they are the State animal:','{"list_1": ["1. Mithun", "2. Clouded leopard", "3. Snow leopard", "4. Red panda"], "list_2": ["Arunachal Pradesh", "Meghalaya", "Himachal Pradesh", "Kerala"], "closing": "How many of the pairs given above are correctly matched?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one pair", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "isCorrect": true}, {"id": "d", "body": "All four pairs", "isCorrect": false}]'::jsonb,2,0.66,'Only three pairs are correct. The mithun is the State animal of Arunachal Pradesh (and Nagaland), the clouded leopard of Meghalaya, and the snow leopard of Himachal Pradesh. The red panda is Sikkim''s State animal; Kerala''s is the Indian elephant.','env-state-animals-pairs','original_pattern_matched','State governments'' notified State symbols (Arunachal Pradesh, Meghalaya, Himachal Pradesh, Sikkim, Kerala).','draft'),
('upsc','Environment & Ecology','Flora, Fungi & Forests','statement_based','medium','Consider the following statements about Neelakurinji (Strobilanthes kunthiana):','{"statements": ["It flowers once in about twelve years.", "It grows in the shola-grassland landscape of the southern Western Ghats, notably around Munnar.", "The plants die after flowering."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "All three", "isCorrect": true}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. Neelakurinji blooms en masse roughly every twelve years (the last mass bloom around Munnar was in 2018), carpeting the montane grasslands blue. Like many Strobilanthes, it is monocarpic: the plants die after flowering and seeding, and the next generation grows from seed.','env-neelakurinji','original_pattern_matched','Kerala Forest Department, Kurinjimala Sanctuary; Botanical Survey of India, Strobilanthes of the Western Ghats.','draft'),
('upsc','Environment & Ecology','Flora, Fungi & Forests','statement_based','medium','Consider the following statements about insectivorous plants:','{"statements": ["They usually grow in soils poor in nitrogen.", "The pitcher plant Nepenthes khasiana is endemic to Meghalaya.", "They cannot photosynthesise and depend wholly on insects for food."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "isCorrect": false}, {"id": "b", "body": "1 and 2", "isCorrect": true}, {"id": "c", "body": "2 and 3", "isCorrect": false}, {"id": "d", "body": "3 only", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Insectivorous plants grow in nitrogen-poor soils and bogs and trap insects to make up the shortfall in nitrogen. India''s only native pitcher plant, Nepenthes khasiana, is endemic to Meghalaya. Statement 3 is wrong: they are green and photosynthesise; insects supply nutrients, not their main food.','env-insectivorous-plants','original_pattern_matched','Botanical Survey of India, Nepenthes khasiana; NCERT Science Class VII (pre-2024 edition), ch. ''Nutrition in Plants''.','draft'),
('upsc','Environment & Ecology','Flora, Fungi & Forests','statement_based','medium','Consider the following statements:','{"statements": ["Orchids growing on tree branches are parasites that draw their food from the host tree.", "Cuscuta (dodder) is a parasitic plant that lacks chlorophyll and takes its food from the host plant."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "isCorrect": false}, {"id": "b", "body": "2 only", "isCorrect": true}, {"id": "c", "body": "Both 1 and 2", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 2 is correct. Most tree-dwelling orchids are epiphytes: they use the tree only for support and make their own food, taking moisture from the air. Cuscuta, by contrast, has no chlorophyll and draws its food from the host through suckers (haustoria). Confusing epiphytes with parasites is the planted trap.','env-epiphyte-vs-parasite','original_pattern_matched','NCERT Science Class VII (pre-2024 edition), ch. ''Nutrition in Plants''; NCERT Biology Class XI, ch. ''Morphology of Flowering Plants''.','draft'),
('upsc','Environment & Ecology','Flora, Fungi & Forests','statement_based','medium','Consider the following statements about bamboo:','{"statements": ["Bamboo is a grass.", "Some bamboo species flower gregariously at long intervals and then die.", "The ''mautam'' in Mizoram is linked to bamboo flowering, which triggers a boom in the rat population.", "Bamboo grown outside forest areas is still treated as a ''tree'' under the Indian Forest Act, 1927, so a permit is needed to fell and transport it."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "Only three", "isCorrect": true}, {"id": "d", "body": "All four", "isCorrect": false}]'::jsonb,2,0.66,'Only statements 1, 2 and 3 are correct. Bamboo belongs to the grass family (Poaceae). Many species flower together after decades and then die; Mizoram''s ''mautam'' follows the roughly 48-year flowering of Melocanna baccifera, whose seeds fuel a rat explosion and famine. Statement 4 is wrong: the Indian Forest (Amendment) Ordinance of November 2017, later enacted, removed bamboo grown on non-forest land from the Act''s definition of ''tree'', so it can be felled and moved without a permit.','env-bamboo-mautam','original_pattern_matched','PIB, Indian Forest (Amendment) Ordinance, 2017 (23 November 2017); National Bamboo Mission.','draft'),
('upsc','Environment & Ecology','Flora, Fungi & Forests','statement_based','easy','Consider the following statements about plants of dry regions:','{"statements": ["Cacti store water in their fleshy stems.", "In many cacti the leaves are reduced to spines, which cuts water loss.", "Such plants usually have large, thin leaves with many open stomata to speed up transpiration."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 and 2 only", "isCorrect": true}, {"id": "b", "body": "2 and 3 only", "isCorrect": false}, {"id": "c", "body": "1 and 3 only", "isCorrect": false}, {"id": "d", "body": "1, 2 and 3", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Xerophytes save water: succulent stems store it, leaves are reduced to spines, and cuticles are thick. Statement 3 describes the opposite -- large, thin leaves with many open stomata would lose water quickly.','env-xerophyte-adaptations','original_pattern_matched','NCERT Biology Class XII, ch. ''Organisms and Populations'' (adaptations of plants to deserts).','draft'),
('upsc','Environment & Ecology','Flora, Fungi & Forests','statement_based','easy','Consider the following statements about the Khejri tree (Prosopis cineraria):','{"statements": ["It is the State tree of Gujarat.", "It was introduced into the Thar Desert from Mexico.", "The Bishnoi sacrifice at Khejarli in 1730 was made to protect sal trees."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": true}]'::jsonb,2,0.66,'None of the statements is correct. Khejri is the State tree of Rajasthan (Gujarat''s is the banyan). It is native to the Thar -- the species introduced from the Americas is a different Prosopis, P. juliflora. The 1730 Khejarli sacrifice, in which Amrita Devi and more than 360 Bishnois gave their lives, was to protect Khejri trees.','env-khejri','original_pattern_matched','Government of Rajasthan, State symbols; Rajasthan Forest Department, Khejri and the Khejarli sacrifice.','draft'),
('upsc','Environment & Ecology','Flora, Fungi & Forests','statement_based','hard','Consider the following statements about invasive plants in India:','{"statements": ["Lantana camara was introduced into India as an ornamental plant.", "Prosopis juliflora, native to Central and South America, was introduced into India.", "Parthenium hysterophorus, native to tropical America, is believed to have entered India with imported food grain.", "Water hyacinth (Eichhornia crassipes) is native to South America."], "closing": "How many of the above statements are correct?", "fixed_option_order": true, "numbering": "roman"}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "Only three", "isCorrect": false}, {"id": "d", "body": "All four", "isCorrect": true}]'::jsonb,2,0.66,'All four statements are correct. Lantana arrived as a garden ornamental in the early 19th century; Prosopis juliflora was introduced from the Americas for fuelwood and to check desert spread; Parthenium (''congress grass'') is thought to have come with imported wheat in the 1950s; water hyacinth, an Amazonian plant, was brought in as an ornamental. All four are now among India''s most damaging invasive plants.','env-invasive-plants','original_pattern_matched','Botanical Survey of India, Invasive Alien Flora of India; ICAR-Directorate of Weed Research, Parthenium.','draft'),
('upsc','Environment & Ecology','Flora, Fungi & Forests','statement_based','hard','Consider the following statements:','{"statements": ["The sandalwood tree is a partial root parasite that draws water and minerals from the roots of other plants.", "Cycas is a flowering plant (angiosperm).", "The coralloid roots of Cycas harbour nitrogen-fixing cyanobacteria."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 and 2 only", "isCorrect": false}, {"id": "b", "body": "2 and 3 only", "isCorrect": false}, {"id": "c", "body": "1 and 3 only", "isCorrect": true}, {"id": "d", "body": "1, 2 and 3", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 3 are correct. Sandalwood (Santalum album) is a hemiparasite: it is green, but its roots tap the roots of host plants. Cycas is a gymnosperm with naked seeds, not a flowering plant; its coralloid roots host nitrogen-fixing cyanobacteria.','env-sandalwood-cycas','original_pattern_matched','NCERT Biology Class XI, ch. ''Plant Kingdom'' (gymnosperms: Cycas); Institute of Wood Science and Technology, sandalwood.','draft'),
('upsc','Environment & Ecology','Flora, Fungi & Forests','mcq','medium','Which one of the following is a flowering plant that grows fully submerged in shallow seas?','{}'::jsonb,'[{"id": "a", "body": "Seagrass", "isCorrect": true}, {"id": "b", "body": "Kelp", "isCorrect": false}, {"id": "c", "body": "Sargassum", "isCorrect": false}, {"id": "d", "body": "Red algae", "isCorrect": false}]'::jsonb,2,0.66,'Seagrasses are flowering plants (angiosperms) that live fully submerged in shallow coastal waters -- the meadows of the Gulf of Mannar and Palk Bay that dugongs graze. Kelp, Sargassum and red algae are algae, not flowering plants.','env-seagrass-angiosperm','original_pattern_matched','Zoological Survey of India / Botanical Survey of India, seagrasses of the Gulf of Mannar; NCERT Biology Class XI, ch. ''Plant Kingdom''.','draft'),
('upsc','Environment & Ecology','Flora, Fungi & Forests','mcq','easy','Which one of the following is a gymnosperm?','{}'::jsonb,'[{"id": "a", "body": "Mango", "isCorrect": false}, {"id": "b", "body": "Neem", "isCorrect": false}, {"id": "c", "body": "Banyan", "isCorrect": false}, {"id": "d", "body": "Pine", "isCorrect": true}]'::jsonb,2,0.66,'Pine is a gymnosperm: its seeds are borne naked on cone scales, not enclosed in a fruit. Mango, neem and banyan are flowering plants (angiosperms).','env-pine-gymnosperm','original_pattern_matched','NCERT Biology Class XI, ch. ''Plant Kingdom''.','draft'),
('upsc','Environment & Ecology','Flora, Fungi & Forests','assertion_reason','easy','Consider the following statements:','{"assertion": "Lichens are often the first organisms to colonise bare rock.", "reason": "Lichens secrete acids that help break the rock down into the beginnings of soil.", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "isCorrect": true}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct and Statement-II explains Statement-I. As pioneer species in primary succession on rock, lichens secrete acids that dissolve the rock and start soil formation, preparing the ground for mosses and later plants.','env-lichen-pioneer','original_pattern_matched','NCERT Biology Class XII, ch. ''Ecosystem'' (ecological succession).','draft'),
('upsc','Environment & Ecology','Flora, Fungi & Forests','assertion_reason','medium','Consider the following statements:','{"assertion": "The Venus flytrap is native to the forests of India.", "reason": "The Venus flytrap is an insectivorous plant.", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "isCorrect": false}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "isCorrect": true}]'::jsonb,2,0.66,'Statement-I is incorrect but Statement-II is correct. The Venus flytrap (Dionaea muscipula) is native only to a small area of the coastal Carolinas in the United States. It is insectivorous, closing its leaves on insects. India''s native insectivorous plants include Nepenthes, Drosera and Utricularia.','env-venus-flytrap','original_pattern_matched','US Fish and Wildlife Service, Dionaea muscipula; Botanical Survey of India, insectivorous plants of India.','draft')
